-- Run with a database administrative test connection.
-- Read-only transaction; no user data or authentication records are changed.
-- Uses existing owned calculations: empty owner fixtures abort instead of passing.
begin read only;
do $test$ begin
perform set_config('request.jwt.claims',jsonb_build_object('sub',(select r.owner_user_id from jyotisha.calculation_runs r where r.owner_user_id is not null and r.deleted_at is null and exists(select 1 from jyotisha.mahadasa_periods m where m.calculation_id=r.id) order by r.created_at desc limit 1),'role','authenticated')::text,true);
if auth.uid() is null then raise exception 'No owned calculation fixture available'; end if;
perform set_config('audit.expected',(jsonb_build_object('calculation_bhava_factors',(select count(*) from jyotisha.calculation_bhava_factors root where jyotisha.user_owns_calculation(root.calculation_run_id)),'calculation_bhaveshas',(select count(*) from jyotisha.calculation_bhaveshas root where jyotisha.user_owns_calculation(root.calculation_run_id)),'calculation_bhava_summaries',(select count(*) from jyotisha.calculation_bhava_summaries root where jyotisha.user_owns_calculation(root.calculation_run_id)),'chart_objects',(select count(*) from jyotisha.chart_objects root where jyotisha.user_owns_calculation(root.calculation_run_id)),'chart_object_links',(select count(*) from jyotisha.chart_object_links root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'chart_layer_status',(select count(*) from jyotisha.chart_layer_status root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'chart_evidence_index',(select count(*) from jyotisha.chart_evidence_index root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'prediction_evidence',(select count(*) from jyotisha.prediction_evidence root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'prediction_windows',(select count(*) from jyotisha.prediction_windows root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'chart_verification_checks',(select count(*) from jyotisha.chart_verification_checks root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'prediction_triggers',(select count(*) from jyotisha.prediction_triggers root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'prediction_results',(select count(*) from jyotisha.prediction_results root where exists(select 1 from jyotisha.chart_objects p0 where p0.id=root.chart_object_id and jyotisha.user_owns_calculation(p0.calculation_run_id))),'antardasa_periods',(select count(*) from jyotisha.antardasa_periods root where exists(select 1 from jyotisha.mahadasa_periods p0 where p0.id=root.mahadasa_id and jyotisha.user_owns_calculation(p0.calculation_id))),'pratyantardasa_periods',(select count(*) from jyotisha.pratyantardasa_periods root where exists(select 1 from jyotisha.antardasa_periods p0 where p0.id=root.antardasa_id and exists(select 1 from jyotisha.mahadasa_periods p1 where p1.id=p0.mahadasa_id and jyotisha.user_owns_calculation(p1.calculation_id)))),'prediction_evaluation_evidence',(select count(*) from jyotisha.prediction_evaluation_evidence root where exists(select 1 from jyotisha.prediction_evaluations p0 where p0.id=root.evaluation_id and jyotisha.user_owns_calculation(p0.calculation_id))),'prediction_modifiers',(select count(*) from jyotisha.prediction_modifiers root where exists(select 1 from jyotisha.prediction_evaluations p0 where p0.id=root.evaluation_id and jyotisha.user_owns_calculation(p0.calculation_id))),'classical_rule_evaluation_evidence',(select count(*) from jyotisha.classical_rule_evaluation_evidence root where exists(select 1 from jyotisha.classical_rule_evaluations p0 where p0.id=root.evaluation_id and jyotisha.user_owns_calculation(p0.calculation_id))),'prediction_synthesis_evaluation_evidence',(select count(*) from jyotisha.prediction_synthesis_evaluation_evidence root where exists(select 1 from jyotisha.prediction_synthesis_evaluations p0 where p0.id=root.synthesis_evaluation_id and jyotisha.user_owns_calculation(p0.calculation_id))),'prediction_modifier_semantics',(select count(*) from jyotisha.prediction_modifier_semantics root where exists(select 1 from jyotisha.prediction_modifiers p0 where p0.id=root.modifier_id and exists(select 1 from jyotisha.prediction_evaluations p1 where p1.id=p0.evaluation_id and jyotisha.user_owns_calculation(p1.calculation_id))))))::text,true);
end $test$;
set local role authenticated;
do $assert$ begin
if current_setting('audit.expected')::jsonb <> jsonb_build_object('calculation_bhava_factors',(select count(*) from jyotisha.calculation_bhava_factors),'calculation_bhaveshas',(select count(*) from jyotisha.calculation_bhaveshas),'calculation_bhava_summaries',(select count(*) from jyotisha.calculation_bhava_summaries),'chart_objects',(select count(*) from jyotisha.chart_objects),'chart_object_links',(select count(*) from jyotisha.chart_object_links),'chart_layer_status',(select count(*) from jyotisha.chart_layer_status),'chart_evidence_index',(select count(*) from jyotisha.chart_evidence_index),'prediction_evidence',(select count(*) from jyotisha.prediction_evidence),'prediction_windows',(select count(*) from jyotisha.prediction_windows),'chart_verification_checks',(select count(*) from jyotisha.chart_verification_checks),'prediction_triggers',(select count(*) from jyotisha.prediction_triggers),'prediction_results',(select count(*) from jyotisha.prediction_results),'antardasa_periods',(select count(*) from jyotisha.antardasa_periods),'pratyantardasa_periods',(select count(*) from jyotisha.pratyantardasa_periods),'prediction_evaluation_evidence',(select count(*) from jyotisha.prediction_evaluation_evidence),'prediction_modifiers',(select count(*) from jyotisha.prediction_modifiers),'classical_rule_evaluation_evidence',(select count(*) from jyotisha.classical_rule_evaluation_evidence),'prediction_synthesis_evaluation_evidence',(select count(*) from jyotisha.prediction_synthesis_evaluation_evidence),'prediction_modifier_semantics',(select count(*) from jyotisha.prediction_modifier_semantics)) then raise exception 'Owned derived row counts changed'; end if;
end $assert$;
select 'owner counts match across 19 tables' as result;
rollback;

begin read only;
set local role authenticated;
do $test$ begin perform set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000091","role":"authenticated"}',true); end $test$;
do $assert$ declare counts jsonb; begin
counts := jsonb_build_object('calculation_bhava_factors',(select count(*) from jyotisha.calculation_bhava_factors),'calculation_bhaveshas',(select count(*) from jyotisha.calculation_bhaveshas),'calculation_bhava_summaries',(select count(*) from jyotisha.calculation_bhava_summaries),'chart_objects',(select count(*) from jyotisha.chart_objects),'chart_object_links',(select count(*) from jyotisha.chart_object_links),'chart_layer_status',(select count(*) from jyotisha.chart_layer_status),'chart_evidence_index',(select count(*) from jyotisha.chart_evidence_index),'prediction_evidence',(select count(*) from jyotisha.prediction_evidence),'prediction_windows',(select count(*) from jyotisha.prediction_windows),'chart_verification_checks',(select count(*) from jyotisha.chart_verification_checks),'prediction_triggers',(select count(*) from jyotisha.prediction_triggers),'prediction_results',(select count(*) from jyotisha.prediction_results),'antardasa_periods',(select count(*) from jyotisha.antardasa_periods),'pratyantardasa_periods',(select count(*) from jyotisha.pratyantardasa_periods),'prediction_evaluation_evidence',(select count(*) from jyotisha.prediction_evaluation_evidence),'prediction_modifiers',(select count(*) from jyotisha.prediction_modifiers),'classical_rule_evaluation_evidence',(select count(*) from jyotisha.classical_rule_evaluation_evidence),'prediction_synthesis_evaluation_evidence',(select count(*) from jyotisha.prediction_synthesis_evaluation_evidence),'prediction_modifier_semantics',(select count(*) from jyotisha.prediction_modifier_semantics));
if exists (select 1 from jsonb_each_text(counts) where value::bigint <> 0) then raise exception 'Unowned derived rows are visible'; end if;
end $assert$;
select 'outsider sees zero rows across 19 tables' as result;
rollback;

begin read only;
set local role anon;
do $assert$ begin
begin
perform 1 from jyotisha.antardasa_periods limit 1;
raise exception 'Anonymous read unexpectedly allowed';
exception when insufficient_privilege then null;
end;
end $assert$;
select 'anonymous access denied' as result;
rollback;
